def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return

    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65

    # Pump vertically to increase height
    if pos.y < target_y:
        if vy > 0:  # Apply upward force when moving upward
            sandbox.apply_force_to_seat(0, 42.0)
        # Apply horizontal correction when close to target y
        if abs(pos.y - target_y) < 0.2:  # Within 0.2m of target y
            if pos.x > target_x_max:
                sandbox.apply_force_to_seat(-42.0, 0)  # Leftward correction
            elif pos.x < target_x_min:
                sandbox.apply_force_to_seat(42.0, 0)   # Rightward correction
    else:
        # At or above target y, adjust x to stay within the target zone
        if pos.x > target_x_max:
            sandbox.apply_force_to_seat(-42.0, 0)
        elif pos.x < target_x_min:
            sandbox.apply_force_to_seat(42.0, 0)
        else:
            # If in target x zone, stabilize by reducing horizontal velocity
            if abs(vel.x) < 1.0:
                # Already at or near apex, do nothing
                sandbox.apply_force_to_seat(0, 0)
            else:
                # Apply horizontal force to reduce speed
                sandbox.apply_force_to_seat(-vx * 10.0, 0)
